using Xunit;
using ReviveOS.WindowsOptimizer;
using ReviveOS.Core;
using System.Text.Json;
public class DeepTests {
 static DeepInventory Inventory(bool? hdd,double[] queue)=>new(hdd,queue,["Spotify","MsMpEng"],false,JsonSerializer.SerializeToElement(new[]{new{Name="SysMain",Status=4}}));
 [Fact] public void PlanNeverDisablesCriticalOrBlindlyDisablesServices(){var plan=DeepPlan.Recommend(Inventory(false,[5,5,5]));Assert.DoesNotContain(plan,x=>x.Id.StartsWith("service:"));Assert.DoesNotContain(plan,x=>x.Id.Contains("MsMpEng"));Assert.Contains(plan,x=>x.Id=="pagefile");Assert.DoesNotContain(DeepPlan.Recommend(Inventory(null,[5,5,5])),x=>x.Id.StartsWith("service:"));}
 [Fact] public void SysMainOnlySuggestedForMeasuredHddPressure(){Assert.Contains(DeepPlan.Recommend(Inventory(true,[2,2,2])),x=>x.Id=="service:SysMain");Assert.DoesNotContain(DeepPlan.Recommend(Inventory(true,[0,0,0])),x=>x.Id.StartsWith("service:"));Assert.DoesNotContain(DeepPlan.Recommend(Inventory(true,[2,2,2])),x=>x.Id=="service:WSearch");}
 [Fact] public void ServicesOutsideAllowlistCannotBeMutated(){Assert.Throws<ArgumentException>(()=>DeepPlan.Describe("service:WinDefend"));Assert.Throws<ArgumentException>(()=>DeepPlan.Describe("service:wuauserv"));Assert.Throws<ArgumentException>(()=>DeepBackend.DisabledAfter("startup:malicious'","{}"));}
 [WindowsFact] public async Task StartupRoundtripPreservesCommandAndOtherValues(){if(!OperatingSystem.IsWindows())throw new PlatformNotSupportedException();using var key=Microsoft.Win32.Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run");var backend=new DeepBackend();var before=await backend.Read("startup:Spotify");var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));var sentinel="ReviveOSTest_"+Guid.NewGuid().ToString("N");key.SetValue(sentinel,"keep");try{key.SetValue("Spotify",@"%USERPROFILE%\test's path\app.exe --test",Microsoft.Win32.RegistryValueKind.ExpandString);var journal=new ChangeJournal(Path.Combine(dir,"changes.json"),backend);await journal.Apply("startup:Spotify",DeepBackend.DisabledAfter("startup:Spotify",(await backend.Read("startup:Spotify"))!));Assert.Null(key.GetValue("Spotify"));Assert.Equal("keep",key.GetValue(sentinel));await journal.Restore();Assert.Equal(@"%USERPROFILE%\test's path\app.exe --test",key.GetValue("Spotify",null,Microsoft.Win32.RegistryValueOptions.DoNotExpandEnvironmentNames));Assert.Equal(Microsoft.Win32.RegistryValueKind.ExpandString,key.GetValueKind("Spotify"));}finally{await backend.Write("startup:Spotify",before);key.DeleteValue(sentinel,false);if(Directory.Exists(dir))Directory.Delete(dir,true);}}
 [WindowsFact] public async Task OptionalServicesAndPagefileCanBeInspectedWithoutMutation(){var backend=new DeepBackend();foreach(var id in new[]{"service:SysMain","service:WSearch","pagefile"}){if(id.StartsWith("service:")){var available=await Commands.CheckedPowerShell("Get-Service -Name '"+id[8..]+"' -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Name");if(string.IsNullOrWhiteSpace(available)){await Assert.ThrowsAsync<IOException>(()=>backend.Read(id));continue;}}var value=await backend.Read(id);using var json=JsonDocument.Parse(value!);Assert.Equal(JsonValueKind.Object,json.RootElement.ValueKind);}}
}
